import React, { useState, useEffect } from "react";
import { useNavigate } from 'react-router-dom';
import HamburgerMenu from '../components/HamburgerMenu';
import './PricingPage.css';

function PricingPage() {
  const [pricingPlans, setPricingPlans] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [paymentLoading, setPaymentLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    fetchPricingPlans();
  }, []);

  const fetchPricingPlans = async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_BASE_URL}/payments/pricing`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          [process.env.REACT_APP_API_KEY_HEADER]: process.env.REACT_APP_API_KEY
        },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch pricing plans');
      }

      const data = await response.json();
      setPricingPlans(data);
    } catch (error) {
      console.error('Error fetching pricing plans:', error);
      setError('Failed to load pricing plans');
    } finally {
      setLoading(false);
    }
  };

  const decodeJWT = (token) => {
    try {
      const [, payloadEncoded] = token.split('.');
      const payload = JSON.parse(atob(payloadEncoded));
      return payload;
    } catch (err) {
      console.error("Invalid JWT token:", err);
      return null;
    }
  };

  const handleSubscribe = async (plan) => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/login');
      return;
    }

    const decoded = decodeJWT(token);
    if (!decoded || !decoded.userId || !decoded.email) {
      setError('Invalid user session. Please login again.');
      navigate('/login');
      return;
    }

    setSelectedPlan(plan);
    setPaymentLoading(true);
    setError(null);

    try {
      // Create order
      const orderResponse = await fetch(`${process.env.REACT_APP_API_BASE_URL}/payments/create-order`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          [process.env.REACT_APP_API_KEY_HEADER]: process.env.REACT_APP_API_KEY
        },
        body: JSON.stringify({
          planId: plan.planId,
          userUid: decoded.userId,
          userEmail: decoded.email
        })
      });

      const orderData = await orderResponse.json();

      if (!orderResponse.ok) {
        throw new Error(orderData.error || 'Failed to create payment order');
      }

      // Initialize Razorpay
      const options = {
        key: orderData.key,
        amount: orderData.amount,
        currency: orderData.currency,
        name: 'NutriSift',
        description: `Subscription for ${orderData.planName}`,
        order_id: orderData.orderId,
        handler: async function (response) {
          // Verify payment
          try {
            const verifyResponse = await fetch(`${process.env.REACT_APP_API_BASE_URL}/payments/verify-payment`, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                [process.env.REACT_APP_API_KEY_HEADER]: process.env.REACT_APP_API_KEY
              },
              body: JSON.stringify({
                razorpayOrderId: response.razorpay_order_id,
                razorpayPaymentId: response.razorpay_payment_id,
                razorpaySignature: response.razorpay_signature,
                userUid: decoded.userId,
                userEmail: decoded.email
              })
            });

            const verifyData = await verifyResponse.json();

            if (verifyResponse.ok) {
              alert('Payment successful! Your subscription is now active.');
              navigate('/meal-planner'); // Redirect to meal planner after successful payment
            } else {
              alert('Payment verification failed: ' + verifyData.error);
            }
          } catch (error) {
            console.error('Payment verification error:', error);
            alert('Payment verification failed. Please contact support.');
          }
        },
        prefill: {
          name: decoded.name || '',
          email: decoded.email,
          contact: decoded.phone || ''
        },
        theme: {
          color: '#4299e1'
        },
        modal: {
          ondismiss: function() {
            setPaymentLoading(false);
            setSelectedPlan(null);
          }
        }
      };

      const rzp = new window.Razorpay(options);
      rzp.open();

    } catch (error) {
      console.error('Payment error:', error);
      setError(error.message);
      setPaymentLoading(false);
      setSelectedPlan(null);
    }
  };

  const formatPrice = (price, currency) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: currency || 'INR'
    }).format(price);
  };

  const getDurationText = (type, value) => {
    switch (type) {
      case 'MONTHLY':
        return value === 1 ? 'per month' : `per ${value} months`;
      case 'YEARLY':
        return value === 1 ? 'per year' : `per ${value} years`;
      case 'LIFETIME':
        return 'one-time payment';
      default:
        return '';
    }
  };

  if (loading) {
    return (
      <div className="pricing-page">
        <header className="pricing-header">
          <h1>� Choose Your Plan</h1>
          <HamburgerMenu isLoggedIn={true} isSidebar={true} />
        </header>
        <div className="pricing-container">
          <div className="loading-state">
            <div className="spinner large"></div>
            <p>Loading pricing plans...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="pricing-page">
      <header className="pricing-header">
        <h1>� Choose Your Plan</h1>
        <HamburgerMenu isLoggedIn={true} isSidebar={true} />
      </header>

      <div className="pricing-container">
        <div className="pricing-content">
          <p className="pricing-subtitle">
            Unlock premium features and take your meal planning to the next level
          </p>

          {error && (
            <div className="pricing-message error">
              {error}
            </div>
          )}

          <div className="pricing-grid">
            {pricingPlans.map((plan) => (
              <div key={plan.planId} className={`pricing-card ${plan.planName.toLowerCase().includes('premium') ? 'featured' : ''}`}>
                {plan.planName.toLowerCase().includes('premium') && (
                  <div className="featured-badge">Most Popular</div>
                )}

                <div className="pricing-header">
                  <span className="plan-icon">💎</span>
                  <h3>{plan.planName}</h3>
                  <p className="plan-description">{plan.description}</p>
                </div>

                <div className="pricing-details">
                  <div className="price-container">
                    <span className="price">
                      {formatPrice(plan.currentPrice, plan.currency)}
                    </span>
                    <span className="duration">
                      {getDurationText(plan.durationType, plan.durationValue)}
                    </span>
                  </div>

                  {plan.discountPercentage > 0 && (
                    <div className="discount-info">
                      <span className="discount-badge">
                        Save {plan.discountPercentage}%
                      </span>
                      <span className="original-price">
                        {formatPrice(plan.originalPrice, plan.currency)}
                      </span>
                    </div>
                  )}
                </div>

                <button
                  className={`subscribe-button ${paymentLoading && selectedPlan?.planId === plan.planId ? 'loading' : ''}`}
                  onClick={() => handleSubscribe(plan)}
                  disabled={paymentLoading}
                >
                  {paymentLoading && selectedPlan?.planId === plan.planId ? (
                    <>
                      <span className="spinner"></span>
                      Processing Payment...
                    </>
                  ) : (
                    `Subscribe to ${plan.planName}`
                  )}
                </button>
              </div>
            ))}
          </div>

          {pricingPlans.length === 0 && !loading && (
            <div className="empty-state">
              <div className="empty-icon">📋</div>
              <h3>No pricing plans available</h3>
              <p>Please check back later or contact support.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default PricingPage;